package bundle

import (
	"bytes"
	"context"
	"embed"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

//go:embed seeds/*
var seeds embed.FS

// FirstRun keeps an emulator from opening its setup wizard: the wizard only
// stays away if the setting below is present, and a config the emulator did
// not create has none of its defaults (controls included), so a missing
// config is created from a complete template generated by the pinned version.
type FirstRun struct {
	Config   string `json:"config"`   // path of the emulator's config file
	Template string `json:"template"` // file in seeds/
	Section  string `json:"section"`
	Key      string `json:"key"`
	Value    string `json:"value"`
	// Controls is a file in seeds/ with gamepad bindings, added next to the
	// emulator's keyboard ones. SDL names buttons by position, so the same
	// bindings serve Xbox and PlayStation pads.
	Controls string `json:"controls,omitempty"`
	// ScreensaverKey, in Section, is turned off when the desktop has no
	// screensaver service; the emulator warns on every game otherwise.
	ScreensaverKey string `json:"screensaverKey,omitempty"`
}

var screensaverService = defaultScreensaverService

// defaultScreensaverService reports whether the desktop offers
// org.freedesktop.ScreenSaver, and whether that could be determined at all.
func defaultScreensaverService() (available, known bool) {
	if _, err := exec.LookPath("busctl"); err != nil {
		return false, false
	}
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	return exec.CommandContext(ctx, "busctl", "--user", "status", "org.freedesktop.ScreenSaver").Run() == nil, true
}

// PrepareFirstRun applies FirstRun before launch. An existing config keeps
// everything else, including gamepad bindings the user already set.
func (e *Emulator) PrepareFirstRun() error {
	if e.FirstRun == nil {
		return nil
	}
	path := e.Expand(e.FirstRun.Config, nil)
	current, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		if current, err = seeds.ReadFile("seeds/" + e.FirstRun.Template); err == nil {
			err = os.MkdirAll(filepath.Dir(path), 0o755)
		}
	}
	if err != nil {
		return err
	}
	updated := setINIValue(current, e.FirstRun.Section, e.FirstRun.Key, e.FirstRun.Value)
	if e.FirstRun.Controls != "" {
		controls, err := seeds.ReadFile("seeds/" + e.FirstRun.Controls)
		if err != nil {
			return err
		}
		updated = addGamepadBindings(updated, controls)
	}
	if e.FirstRun.ScreensaverKey != "" {
		if available, known := screensaverService(); known {
			value := "false"
			if available {
				value = "true"
			}
			updated = setINIValue(updated, e.FirstRun.Section, e.FirstRun.ScreensaverKey, value)
		}
	}
	if bytes.Equal(updated, current) {
		if _, err := os.Stat(path); err == nil {
			return nil
		}
	}
	return os.WriteFile(path, updated, 0o644)
}

// addGamepadBindings adds each section of controls to ini, unless that section
// already has a gamepad binding. Emulators read repeated keys as alternatives,
// so the keyboard bindings keep working.
func addGamepadBindings(ini, controls []byte) []byte {
	out := ini
	section := ""
	var entries []string
	flush := func() {
		if section != "" && len(entries) > 0 {
			out = addINILines(out, section, entries)
		}
		entries = nil
	}
	for _, line := range strings.Split(string(controls), "\n") {
		t := strings.TrimSpace(line)
		switch {
		case strings.HasPrefix(t, "["):
			flush()
			section = t
		case t != "":
			entries = append(entries, t)
		}
	}
	flush()
	return out
}

// addINILines inserts entries at the start of a section, creating it if
// needed, and does nothing if the section already mentions SDL devices.
func addINILines(ini []byte, header string, entries []string) []byte {
	lines := strings.Split(string(ini), "\n")
	for i, line := range lines {
		if strings.TrimSpace(line) != header {
			continue
		}
		for _, l := range lines[i+1:] {
			t := strings.TrimSpace(l)
			if strings.HasPrefix(t, "[") {
				break
			}
			if strings.Contains(t, "SDL-") {
				return ini
			}
		}
		added := make([]string, len(entries))
		for j, entry := range entries {
			added[j] = entry
			if strings.HasSuffix(line, "\r") {
				added[j] += "\r"
			}
		}
		lines = append(lines[:i+1], append(added, lines[i+1:]...)...)
		return []byte(strings.Join(lines, "\n"))
	}
	return []byte(strings.TrimRight(string(ini), "\r\n") + "\n\n" + header + "\n" + strings.Join(entries, "\n") + "\n")
}

// setINIValue sets a key in an INI file, leaving every other line untouched.
func setINIValue(ini []byte, section, key, value string) []byte {
	lines := strings.Split(string(ini), "\n")
	entry := key + " = " + value
	header := "[" + section + "]"
	in := false
	insertAt := -1
	for i, line := range lines {
		t := strings.TrimSpace(line)
		if strings.HasPrefix(t, "[") {
			in = t == header
			if in {
				insertAt = i + 1
			}
			continue
		}
		if name, _, ok := strings.Cut(t, "="); in && ok && strings.TrimSpace(name) == key {
			if strings.HasSuffix(line, "\r") {
				entry += "\r"
			}
			lines[i] = entry
			return []byte(strings.Join(lines, "\n"))
		}
	}
	if insertAt < 0 {
		return []byte(strings.TrimRight(string(ini), "\r\n") + "\n\n" + header + "\n" + entry + "\n")
	}
	lines = append(lines[:insertAt], append([]string{entry}, lines[insertAt:]...)...)
	return []byte(strings.Join(lines, "\n"))
}
